import {uid,clone} from '../document/model.js';
export function audioClips(audio){return !audio?[]:audio.clips??[{id:'audio-'+audio.assetId,name:audio.name,offset:audio.offset,trimStart:audio.trimStart,trimEnd:audio.trimEnd}];}
export function splitAudio(audio,id,time){const clips=clone(audioClips(audio)),i=clips.findIndex(c=>c.id===id),c=clips[i];if(!c||time<=c.offset||time>=c.offset+c.trimEnd-c.trimStart)throw Error('Place the playhead inside the recorded block before splitting.');const cut=c.trimStart+time-c.offset,right={...c,id:uid(),name:c.name+' · part 2',offset:time,trimStart:cut};c.trimEnd=cut;clips.splice(i+1,0,right);audio.clips=clips;return right.id;}
export function trimAudio(audio,id,start,end){const clips=clone(audioClips(audio)),c=clips.find(c=>c.id===id);if(!c||start<c.offset||end>c.offset+c.trimEnd-c.trimStart||end<=start)throw Error('Trim boundaries must stay inside the selected recorded block.');c.trimEnd=c.trimStart+end-c.offset;c.trimStart+=start-c.offset;c.offset=start;audio.clips=clips;return c;}
